        vel.X, vel.Y, vel.Z, u, t, v, vu, vt, vv, ttcMs, horizonMs };
    if (!first.ContainsKey(reason)) first[reason] = sample;
    if (recent.Count == 48) recent.Dequeue();
    recent.Enqueue(sample);
}
